<script setup>
import { computed, ref, watch, onMounted, onUnmounted } from 'vue'
import PolicySwitch from './PolicySwitch.vue'
import TelegramIdentityCard from './TelegramIdentityCard.vue'
import TelegramTestMessage from './TelegramTestMessage.vue'
import TelegramActionConfirm from './TelegramActionConfirm.vue'
import { readNotifications,saveNotifications,testNotifications,connectTelegram,confirmTelegram,disconnectTelegram,choosePublicBot,choosePersonalBot,syncPersonalBot,rotatePersonalSecret,initializeTelegram } from '../api/notifications.js'
const props=defineProps({target:{type:String,default:''},owner:Boolean})
const current=ref(null),enabled=ref(false),registration=ref(false),privateTarget=ref(false),link=ref('')
const busy=ref(false),error=ref(''),message=ref(''),cooldown=ref(false),setupOpen=ref(false),personalForm=ref(false),choicesOpen=ref(false),token=ref(''),exclusive=ref(false)
const dirty=computed(()=>current.value&&(enabled.value!==current.value.enabled||registration.value!==current.value.events.registration||privateTarget.value!==current.value.private_target))
const canSave=computed(()=>dirty.value&&(!enabled.value||(current.value.available&&current.value.bound&&privateTarget.value)))
const canTest=computed(()=>current.value?.available&&current.value.bound&&current.value.enabled&&!dirty.value&&!cooldown.value)
const ownerAccount=computed(()=>current.value?.owner_account??(props.owner&&!props.target))
const showChoices=computed(()=>!ownerAccount.value&&(!current.value?.bot_mode||choicesOpen.value||personalForm.value))
watch(privateTarget,value=>{if(!value)enabled.value=false})
const pendingAction=ref(''),candidateConfirmed=ref(false)
function requestAction(action){if(current.value?.bound||['disconnect','rotate'].includes(action))pendingAction.value=action;else if(action==='replace')editPersonal();else operation(action)}
function confirmAction(){const action=pendingAction.value;pendingAction.value='';if(action==='replace')editPersonal();else operation(action)}
let controller,timer,cooldownTimer,live=true
function adopt(v){setupOpen.value=false;candidateConfirmed.value=false;current.value=v;enabled.value=v.enabled;registration.value=v.events.registration;privateTarget.value=v.private_target;if(v.bound||v.pairing.state==='none')link.value=''}
function editPersonal(){if(!current.value?.personal_available){setupOpen.value=true;return}personalForm.value=true;choicesOpen.value=true;token.value='';exclusive.value=false}
function cancelPersonal(){personalForm.value=false;token.value='';exclusive.value=false}
async function operation(action='read',testMessage){
 if(busy.value)return
 busy.value=true;error.value='';message.value='';controller=new AbortController();timer=setTimeout(()=>controller.abort(),12000)
 try{
  if(action==='test'){await testNotifications(current.value.revision,controller.signal,props.target,testMessage);if(live)message.value='Telegram 已确认测试消息发送成功。'}
  else if(action==='connect'){
   const pairing=await connectTelegram(current.value.revision,controller.signal,props.target)
   if(live)link.value=pairing.url
   const v=await readNotifications(controller.signal,props.target);if(live)adopt(v)
  }else{
   let v
   if(action==='initialize')v=await initializeTelegram(controller.signal)
   else if(action==='personal'){
    const submitted=token.value;token.value=''
    v=await choosePersonalBot(submitted,exclusive.value,current.value.revision,controller.signal,props.target)
   }else if(action==='choose-public')v=await choosePublicBot(current.value.revision,controller.signal,props.target)
   else if(action==='sync')v=await syncPersonalBot(current.value.revision,controller.signal,props.target)
   else if(action==='rotate')v=await rotatePersonalSecret(current.value.revision,controller.signal,props.target)
   else if(action==='confirm')v=await confirmTelegram(current.value.revision,controller.signal,props.target,current.value.candidate_identity?.user_id)
   else if(action==='disconnect')v=await disconnectTelegram(current.value.revision,controller.signal,props.target)
   else if(action==='save')v=await saveNotifications({enabled:enabled.value,private_target:privateTarget.value,events:{registration:registration.value,account_security:false,tool_outcomes:false,system_errors:false},expected_revision:current.value.revision},controller.signal,props.target)
   else v=await readNotifications(controller.signal,props.target)
   if(live){adopt(v);if(['personal','choose-public','disconnect'].includes(action)){cancelPersonal();choicesOpen.value=false}
    if(action!=='read')message.value={initialize:'安全存储已就绪，可以绑定 Bot。',personal:'Bot 身份已验证，Token 已加密保存。请继续完成私聊配对。','choose-public':'已选择公共 Bot。接下来验证 Telegram 身份。',sync:v.pairing.state==='confirm'?'已读取私聊证明，请核对后确认。':'同步完成，尚未收到有效配对。确认已在 Telegram 点击 Start；消息较多时可稍后再同步。',rotate:'密文已用当前首选密钥重新加密，身份与偏好未改变。',confirm:'身份已验证。选择私聊目标后保存启用。',disconnect:'已断开并清除 Bot、身份、目标与所有偏好。',save:'消息设置已保存。'}[action]
   }
  }
 }catch(cause){if(live){error.value=cause.name==='AbortError'?'操作结果未确认，请刷新后核对；不要立即重复发送。':cause.message;if([404,503].includes(cause.status)||!current.value)setupOpen.value=true;if([401,403,404,503].includes(cause.status)){current.value=null;link.value='';cancelPersonal()}}}
 finally{token.value='';clearTimeout(timer);if(live){busy.value=false;if(action==='test'){cooldown.value=true;cooldownTimer=setTimeout(()=>cooldown.value=false,300000)}}}
}
onMounted(()=>operation())
onUnmounted(()=>{live=false;controller?.abort();clearTimeout(timer);clearTimeout(cooldownTimer);token.value='';link.value=''})
</script>

<template>
<div class="notification-settings" :aria-busy="busy">
 <header class="connection-summary" :class="{connected:current?.bound&&current.available}"><span class="telegram-symbol" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none"><path d="m4 10 16-6-4 16-5-6-7-4Z" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/><path d="m11 14 5-6" stroke="currentColor" stroke-width="1.6"/></svg></span><div><h3>{{current?.bound?(current.available?'Telegram 已连接':'Telegram 连接待检查'):'Telegram 通知'}}</h3><p class="binding-state">{{!current?'正在检查服务':current.bound?'@'+(current.bot_username||'Bot')+' · '+(ownerAccount?'平台 Bot':current.bot_mode==='public'?'公共 Bot':'个人 Bot'):current.bot_mode?'完成私聊验证，即可接收通知':'连接你的 Bot，让消息抵达 Telegram'}}</p></div><span class="connection-badge">{{!current?(busy?'检查中':'暂不可用'):current.bound?(current.available?'已验证':'路由不可用'):'默认关闭'}}</span></header>
 <p v-if="props.target" class="manager-note">正在管理指定账户。配对需目标 Telegram 身份操作，并由当前管理会话确认。</p><p v-if="busy" role="status" class="notification-feedback">正在处理，请稍候…</p><p v-if="error" role="alert" class="notification-error">{{error}}</p><p v-if="message" role="status" class="notification-success">{{message}}</p>
 <div v-if="!current&&!busy" class="deployment-notice">消息服务暂不可用，请重新检查状态。现有连接不会由此页面自动清除。</div>
 <section v-if="ownerAccount&&!current?.bot_mode&&!personalForm" class="owner-bind-panel"><div><h4>绑定你的 Telegram Bot</h4><p>验证后，它将成为其他账户可选的公共 Bot。你的通知仍由你主动开启。</p></div><button v-if="current&&!current.personal_available" type="button" class="initialize-telegram" :disabled="busy" @click="operation('initialize')">初始化安全存储</button><button class="choose-personal primary" type="button" :disabled="busy||!current?.personal_available" @click="editPersonal">绑定 Telegram Bot</button></section>
 <div v-if="showChoices" class="bot-choices"><section><h4>使用公共 Bot</h4><p>使用所有者已验证的 Bot，以自己的 Telegram 身份连接。</p><button class="choose-public" type="button" :disabled="busy||!current?.public_available" @click="operation('choose-public')">使用公共 Bot</button><small v-if="!current?.public_available">等待所有者绑定 Bot</small></section><section><h4>连接个人 Bot</h4><p>使用你独立控制的机器人，凭据在服务端加密保存。</p><button class="choose-personal" type="button" :disabled="busy||!current?.personal_available" @click="editPersonal">绑定个人 Bot</button></section></div>
 <form v-if="personalForm" class="personal-bot-form" @submit.prevent="operation('personal')"><h4>{{ownerAccount?'绑定平台 Bot':'绑定你的专用 Bot'}}</h4><p>从 BotFather 获取 Token，仅用于本次安全验证。提交或离开后输入会清空。</p><label for="personal-bot-token">Bot Token</label><input id="personal-bot-token" v-model="token" type="password" autocomplete="off" spellcheck="false" autocapitalize="off" maxlength="101" required :disabled="busy" placeholder="粘贴 BotFather 提供的 Token" /><label class="exclusive-control"><input v-model="exclusive" type="checkbox" required :disabled="busy" /><span>我控制此 Bot，且它专用于本平台，没有其他程序轮询或现有 webhook。</span></label><p v-if="current?.bot_mode">新 Bot 会清除现有身份、目标与订阅。</p><div class="binding-actions"><button class="personal-submit primary" type="submit" :disabled="busy||!exclusive||!token">验证并加密保存</button><button type="button" :disabled="busy" @click="cancelPersonal">取消</button></div></form>
 <section v-if="current?.bot_mode" class="telegram-binding"><div v-if="!current.bound" class="notification-section-heading"><h4>{{ownerAccount?'平台 Bot':current.bot_mode==='personal'?'个人 Bot':'公共 Bot'}} <span>@{{current.bot_username||'暂不可用'}}</span></h4><button type="button" :disabled="busy" @click="operation()">检查连接状态</button></div><p v-if="!current.available" class="notification-error">当前 Bot 路由不可用，请重新检查状态。</p><p v-if="current.paused" class="notification-error">上次发送失败，通知已暂停。检查机器人是否被屏蔽，再保存启用。</p><div v-if="!current.bound" class="binding-actions"><button class="telegram-connect primary" type="button" :disabled="busy||!current.available" @click="operation('connect')">连接 Telegram</button><button v-if="!ownerAccount" type="button" :disabled="busy" @click="choicesOpen=!choicesOpen;cancelPersonal()">选择另一种 Bot</button></div>
 <div v-if="current.pairing.state!=='none'" class="telegram-pairing" role="region" aria-label="Telegram 配对步骤"><h4>验证 Telegram 身份</h4><ol><li>打开一次性链接，在{{props.target?'目标身份的':'自己的'}} Telegram 私聊中点击 Start。</li><li>返回同步消息，再核对下方完整身份。</li></ol><div class="pair-actions"><a v-if="link" class="telegram-pair-link" :href="link" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">打开 Telegram 配对 ↗</a><button class="sync-personal" type="button" :disabled="busy||!current.available" @click="operation('sync')">同步 Bot 消息</button></div><p v-if="!link">链接只在创建时显示；尚未点击 Start 时可重新连接。</p><p>五分钟有效，仅用一次。不要分享链接；用户名可变化，请核对 User ID。</p><template v-if="current.pairing.state==='confirm'"><TelegramIdentityCard :identity="current.candidate_identity" pending /><label v-if="current.candidate_identity" class="candidate-acknowledgement"><input v-model="candidateConfirmed" type="checkbox" :disabled="busy" /><span>我已核对，这是预期的 Telegram 账户。</span></label><p v-else class="notification-error">当前服务尚未提供完整候选身份，请更新服务后再核对。</p><button class="telegram-confirm primary" type="button" :disabled="busy||!candidateConfirmed||!current.candidate_identity" @click="operation('confirm')">{{props.target?'确认目标 Telegram':'确认我的 Telegram'}}</button></template></div></section>
 <div v-if="current?.bound" class="connected-layout"><section class="verified-identity" aria-labelledby="verified-identity-title"><h4 id="verified-identity-title">已验证的账户</h4><TelegramIdentityCard :identity="current.identity" /><p class="identity-caption">User ID 标识 Telegram 账户；Chat ID 标识接收消息的私聊。已验证私聊中两者数值相同。</p></section><form class="delivery-preferences" @submit.prevent="operation('save')"><fieldset :disabled="busy" class="notification-fields"><legend>接收与订阅</legend><PolicySwitch v-model="privateTarget" label="接收目标 · 已验证私聊" :description="current.identity?'Chat ID '+current.identity.chat_id:'现有已验证私聊 '+current.destination" :disabled="!current.available" /><PolicySwitch v-model="enabled" :label="props.target?'启用此账户通知':'启用我的通知'" :description="!current.available&&current.enabled?'已保存开启，但路由不可用，当前无法发送':'仅发送到当前已选择的私聊'" :disabled="(!current.available||!privateTarget)&&!enabled" /><div class="event-heading"><h4>订阅事件</h4><span>已接入的事件源</span></div><PolicySwitch v-model="registration" label="注册申请" :disabled="!current.supported.registration" :description="current.supported.registration?'收到待审核申请时提醒':'仅所有者与管理员可订阅'" /><details class="unsupported-events"><summary>其他事件与群组支持</summary><p>账户安全、工具结果、系统错误尚未接入。群组发现、成员过滤及多目标仍待后续，目前仅支持已验证私聊。</p></details><div class="notification-actions"><span>{{dirty?'有未保存更改':'偏好已同步'}}</span><button class="notification-save primary" type="submit" :disabled="!canSave">保存偏好</button></div></fieldset></form><TelegramTestMessage class="test-section" :busy="busy" :can-send="canTest" :cooldown="cooldown" :custom-available="current.custom_test_available" @send="value=>operation('test',value)" /></div>
 <details v-if="current?.bot_mode" class="connection-actions"><summary>连接管理<span>更换、重新验证与断开</span></summary><div class="binding-actions"><button v-if="current.bound" class="telegram-connect" type="button" :disabled="busy" @click="requestAction('connect')">重新验证身份</button><button v-if="ownerAccount||current.bot_mode==='personal'" class="replace-bot" type="button" :disabled="busy" @click="requestAction('replace')">更换 Bot</button><button v-if="current.bot_mode==='personal'" class="rotate-secret" type="button" :disabled="busy||!current.available" @click="requestAction('rotate')">重新加密凭据</button><button class="telegram-disconnect danger" type="button" :disabled="busy" @click="requestAction('disconnect')">断开并清除</button></div></details>
 <footer class="settings-help"><span>仅作用于当前账户</span><button class="refresh-notifications" type="button" :disabled="busy" @click="operation()">重新检查状态</button></footer><p v-if="setupOpen" class="activation-needed" role="status">消息服务尚未就绪，请稍后检查状态；未启用的功能不会投递通知。</p><TelegramActionConfirm :action="pendingAction" @cancel="pendingAction=''" @confirm="confirmAction" />
</div></template>
<style scoped>
.notification-settings{min-width:0;background:var(--surface);border:1px solid #dce5e9;border-radius:14px;padding:26px 28px}.connection-summary{display:flex;align-items:center;gap:13px;padding-bottom:22px;border-bottom:1px solid var(--line)}.telegram-symbol{display:grid;place-items:center;background:#edf4f5;color:var(--accent);width:44px;height:44px;border-radius:10px;flex-shrink:0;font-size:28px}.telegram-symbol svg{width:25px;height:25px}.connection-summary h3{margin:0;font-size:19px;font-weight:600;letter-spacing:-.025em}.binding-state{font-size:11px;margin:6px 0 0;color:var(--muted);line-height:1.6;overflow-wrap:anywhere}.connection-summary>div{min-width:0;flex:1}.connection-badge{white-space:nowrap;border-radius:20px;background:#f0f3f5;color:#60717b;font-size:10px;padding:6px 10px}.connected .connection-badge{background:#e7f4ee;color:#216b51}.notification-settings button{min-height:40px;padding:0 14px;border:1px solid #cedbdf;border-radius:7px;background:white;color:var(--ink);font:inherit;font-size:12px;cursor:pointer}.notification-settings button:disabled{opacity:.5;cursor:not-allowed}.notification-settings .primary{background:var(--accent);border-color:var(--accent);color:white}.notification-settings .danger{color:var(--danger)}.notification-settings :is(button,input,a,summary):focus-visible{outline:3px solid var(--focus);outline-offset:3px}h4{font-size:13px;font-weight:600;margin:0 0 12px}.owner-bind-panel{padding:24px 0 2px;display:flex;align-items:center;gap:16px}.owner-bind-panel>div{flex:1;min-width:0}.owner-bind-panel h4{font-size:16px;margin-bottom:8px}.owner-bind-panel p,.bot-choices p{font-size:12px;line-height:1.8;color:var(--muted);margin:0}.owner-bind-panel button{flex-shrink:0}.bot-choices{display:grid;grid-template-columns:1fr 1fr;gap:24px;padding-top:24px}.bot-choices section{padding-left:16px;border-left:2px solid #d2e7e4}.bot-choices button{margin-top:14px}.bot-choices small{display:block;font-size:10px;color:var(--muted);margin-top:8px}.personal-bot-form{margin-top:22px;max-width:620px}.personal-bot-form h4{font-size:15px}.personal-bot-form>p{font-size:12px;line-height:1.8;color:var(--muted)}.personal-bot-form>label:not(.exclusive-control){display:block;font-size:12px;margin:16px 0 8px}input[type=password]{width:100%;min-height:44px;padding:10px 12px;border:1px solid #c4d5d9;border-radius:7px;font:inherit;font-size:14px;box-sizing:border-box}.exclusive-control,.candidate-acknowledgement{display:grid;grid-template-columns:18px minmax(0,1fr);gap:10px;align-items:start;font-size:12px;color:var(--muted);line-height:1.8;margin-top:16px}.exclusive-control input,.candidate-acknowledgement input{box-sizing:border-box;width:18px;height:18px;min-height:0;padding:0;margin:2px 0 0;accent-color:var(--accent)}.binding-actions,.pair-actions{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin-top:16px}.telegram-binding{padding-top:18px}.notification-section-heading{display:flex;align-items:center;justify-content:space-between;gap:14px}.notification-section-heading h4{margin:0;font-size:12px;color:var(--muted);font-weight:400}.notification-section-heading h4 span{margin-left:6px;color:var(--ink);font-weight:550;overflow-wrap:anywhere}.notification-section-heading>button{border:0;background:transparent;color:var(--accent);font-size:11px;padding-right:0;flex-shrink:0}.telegram-pairing{margin-top:16px;padding:18px 20px;border-left:3px solid var(--accent);background:#f7fafb}.telegram-pairing ol{font-size:12px;color:var(--muted);line-height:1.9;padding-left:18px;margin:0}.telegram-pairing p{font-size:11px;line-height:1.8;color:var(--muted)}.telegram-pair-link{display:inline-flex;align-items:center;min-height:40px;color:var(--accent);font-size:12px;font-weight:550}.telegram-confirm{margin-top:14px}.connected-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.12fr);column-gap:34px;row-gap:22px;margin-top:18px}.verified-identity{padding-top:6px}.identity-caption{font-size:11px;line-height:1.9;color:var(--muted);margin:14px 0 0;max-width:50ch}.notification-fields{border:0;padding:0;margin:0;min-width:0}legend{font-size:13px;font-weight:600;margin-bottom:4px;padding:0}.notification-fields :deep(.policy-switch){padding:12px 0;gap:14px}.notification-fields :deep(.switch-copy strong){font-size:12px}.notification-fields :deep(.switch-copy small){font-size:10px;line-height:1.7}.event-heading{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-top:18px}.event-heading h4{margin:0;font-size:12px}.event-heading span{font-size:10px;color:var(--muted)}.unsupported-events{font-size:11px;color:var(--muted);line-height:1.8;margin-top:12px}.unsupported-events summary{cursor:pointer;min-height:32px;align-content:center}.notification-actions{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:12px}.notification-actions>span{font-size:10px;color:var(--muted)}.test-section{grid-column:1;grid-row:2}.delivery-preferences{grid-column:2;grid-row:1/span 2}.connection-actions{margin-top:24px;padding-top:16px;border-top:1px solid var(--line)}.connection-actions>summary{font-size:12px;cursor:pointer;min-height:36px;align-content:center}.connection-actions>summary span{margin-left:10px;color:var(--muted);font-size:10px}.connection-actions .binding-actions{margin-top:8px}.settings-help{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:22px;padding-top:14px;border-top:1px solid var(--line)}.settings-help>span{font-size:10px;color:var(--muted)}.settings-help>button{border:0;color:var(--accent);padding-right:0;font-size:11px}.manager-note{font-size:12px;line-height:1.8;border-left:3px solid var(--accent);padding-left:12px;color:var(--muted)}.notification-error,.notification-success,.notification-feedback,.activation-needed{font-size:12px;line-height:1.8;padding:10px 12px;border-radius:6px;margin:14px 0}.notification-error{color:var(--danger);background:var(--danger-soft)}.notification-success{color:var(--accent);background:#edf6f2}.notification-feedback,.activation-needed{color:var(--muted);background:#f4f6f7}.deployment-notice{font-size:12px;padding:16px 0;color:var(--muted)}
@media(max-width:760px){.connected-layout{grid-template-columns:minmax(0,1fr);gap:22px}.delivery-preferences{border-top:1px solid var(--line);padding-top:20px}.owner-bind-panel{align-items:flex-start;flex-direction:column}.owner-bind-panel button{width:100%}.test-section{grid-column:auto;grid-row:auto}.delivery-preferences{grid-column:auto;grid-row:auto}}@media(max-width:600px){.notification-settings{padding:20px 17px;border-radius:12px}.connection-summary{gap:10px;padding-bottom:18px;flex-wrap:wrap}.telegram-symbol svg{width:25px;height:25px}.connection-summary h3{font-size:17px}.telegram-symbol{width:38px;height:38px;border-radius:9px}.connection-badge{font-size:9px;padding:5px 7px}.bot-choices{grid-template-columns:1fr;gap:24px}.binding-actions button{flex:1}.telegram-pairing{padding:16px 13px}.notification-section-heading{align-items:flex-start}.notification-section-heading h4 span{display:block;margin:5px 0 0}.settings-help{align-items:flex-start;flex-wrap:wrap}.connection-actions .binding-actions{display:grid;grid-template-columns:1fr}.connection-actions>summary span{display:block;margin:5px 0 0 15px}}@media(prefers-reduced-motion:reduce){.notification-settings :deep(*){transition:none!important;animation:none!important}}
</style>